<?php
require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/office2.php';require_once __DIR__.'/../includes/invoice_render.php';
office2_require();
$scope=$_POST['scope']??$_GET['scope']??'business';$id=filter_var($_POST['target_id']??$_GET['target_id']??0,FILTER_VALIDATE_INT);
if(!in_array($scope,['business','branch'],true)){http_response_code(400);exit('Invalid invoice scope.');}
$businesses=$pdo->query('SELECT id,name FROM businesses ORDER BY name,id')->fetchAll();$branches=$pdo->query('SELECT s.id,s.name,s.city,s.business_id,b.name AS business_name FROM shops s JOIN businesses b ON b.id=s.business_id ORDER BY b.name,s.id')->fetchAll();
if(!$id)$id=(int)(($scope==='business'?$businesses:$branches)[0]['id']??0);
$target=null;foreach($scope==='business'?$businesses:$branches as $r)if((int)$r['id']===$id)$target=$r;
if(!$target&&$id){http_response_code(404);exit(__t('Business or branch not found.','تجارت یا شعبه یافت نشد.','سوداګري یا څانګه ونه موندل شوه.'));}
$error='';$brand=$target?($scope==='business'?invoice_business_brand($id):invoice_effective_brand($id)):invoice_default_brand();$layout=invoice_layout($brand);
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 try{
  if(!$target)throw new InvalidArgumentException('Choose a business or branch.');
  if(($_POST['designer_action']??'')==='preview'){
   if(!csrf_verify($_POST['csrf_token']??''))throw new RuntimeException('Invalid form session.',403);
   $raw=$_POST['layout_json']??'';if(!is_string($raw)||strlen($raw)>65536)throw new InvalidArgumentException('Invalid layout.');
   $layout=invoice_layout_validate(json_decode($raw,true,32,JSON_THROW_ON_ERROR));$brand=invoice_brand_validate($_POST,$brand);$brand['auto_print_invoice']='0';[$sale,$items]=invoice_preview_data($layout);invoice_render($sale,$items,$brand,$layout,true);exit;
  }
  invoice_designer_save($_POST,$_FILES);set_flash(__t('Invoice design saved.','دیزاین بل ذخیره شد.','د بل بڼه خوندي شوه.'),'success');redirect(BASE_URL.'admin/invoice_designer.php?'.http_build_query(['scope'=>$scope,'target_id'=>$id]));
 }catch(Throwable $e){http_response_code(in_array($e->getCode(),[403,409],true)?$e->getCode():422);$error=public_error($e);if(($_POST['designer_action']??'')==='preview'){header('Content-Type: application/json; charset=UTF-8');echo json_encode(['error'=>$error]);exit;}}
}
$pageTitle=__t('Invoice designer','دیزاین بل','د بل بڼه');require __DIR__.'/../includes/header.php';
function design_label(string $en,string $da,string $ps=''): string {return __t($en,$da,$ps?:$en);}
function design_input(string $key,string $en,string $da,array $brand,string $type='text'): void { ?><label><?= design_label($en,$da) ?><input class="form-control" name="<?= sanitize($key) ?>" type="<?= sanitize($type) ?>" value="<?= sanitize($brand[$key]??'') ?>" maxlength="255"></label><?php }
function design_select(string $key,string $en,string $da,array $options,array $brand): void { ?><label><?= design_label($en,$da) ?><select class="form-control" name="<?= sanitize($key) ?>"><?php foreach($options as $value=>$text):?><option value="<?= sanitize($value) ?>" <?= ($brand[$key]??'')===(string)$value?'selected':'' ?>><?= sanitize($text) ?></option><?php endforeach ?></select></label><?php }
?>
